#!/usr/bin/env python3
"""Self-contained price/entry/exit/equity replay for the frozen experiment ledger."""
import argparse
from html import escape
import json
from pathlib import Path

LABELS={'ema_original':'原4h均线策略','ema_reversed':'原均线信号反转','ema_daily_filter':'日线顺势过滤','bollinger_20_atr':'震荡回归20＋ATR退出','daily_sma10_40_atr':'日线SMA10/40＋ATR退出（事后高收益）'}


def write_view(path):
    source=json.loads(path.read_text());output=path.parent
    details={}
    for model,windows in source['details'].items():
        details[model]={}
        for name,record in windows.items():
            details[model][name]=dict(metrics=record['metrics'],equity=record['equity'],trades=[{k:t[k] for k in ('symbol','side','entry_at','exit_at','entry_price','exit_price','exit_reason','net_pnl','initial_margin','notional')} for t in record['trades']])
    data=dict(start=source['start'],end=source['end'],prices=source['prices'],windows=source['windows'],details=details,eligible=[x['model'] for x in source['eligible']],labels=LABELS)
    preferred=source['eligible'][0]['model'] if source['eligible'] else next(iter(details))
    recent_trades=details[preferred]['review_month']['trades']
    data['default_symbol']=recent_trades[0]['symbol'] if recent_trades else 'BTC'
    options=''.join(f'<option value="{escape(name)}"'+(' selected' if name==preferred else '')+f'>{escape(LABELS.get(name,name))}</option>' for name in details)
    rows=''
    for name,windows in details.items():
        full=windows.get('full',{}).get('metrics',{});recent=windows.get('review_month',{}).get('metrics',{})
        if not full or not recent:continue
        cls='positive' if recent['return_pct']>0 else 'negative'
        rows+=f'<tr><td>{escape(LABELS.get(name,name))}</td><td>{full["return_pct"]:+.2f}%</td><td>{full["max_drawdown_pct"]:.2f}%</td><td class="{cls}">{recent["return_pct"]:+.2f}%</td><td>{recent["max_drawdown_pct"]:.2f}%</td><td>{recent["trade_count"]}</td></tr>'
    vendor=Path(__file__).resolve().parents[1]/'dashboard'/'static'/'vendor'
    runtime=(vendor/'lightweight-charts.js').read_text().replace('</script','<\\/script')
    license_text=escape((vendor/'lightweight-charts.LICENSE').read_text())
    html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>加密合约策略实验｜行情与交易回放</title><style>
*{box-sizing:border-box}body{margin:0;background:#10181d;color:#d6e1e7;font:14px system-ui;line-height:1.8}main{max-width:1350px;margin:auto;padding:28px 22px}h1{font-size:28px;margin-bottom:8px}h2{font-size:18px}p,.muted{color:#9bb0bd}.eyebrow{color:#dfb477;font-size:12px;letter-spacing:2px}.panel{background:#18242b;border:1px solid #2b3c46;border-radius:12px;padding:20px;margin:18px 0}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:14px}.controls label{display:grid;gap:5px;font-size:12px;color:#9bb0bd}select,button{font:inherit;background:#233743;color:#d6e1e7;border:1px solid #3c5260;border-radius:7px;padding:10px;cursor:pointer}select{max-width:100%}button:disabled{opacity:.4}.slider{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.slider input{flex:1;min-width:160px;accent-color:#65c4aa}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{padding:15px;background:#1d2e37;border-radius:8px}.stat strong{display:block;font-size:23px}.stat span{font-size:12px;color:#9bb0bd}.positive{color:#65c4aa}.negative{color:#ef8b87}#price-chart{height:360px}#equity-chart{height:260px}.table{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{text-align:right;padding:10px;border-bottom:1px solid #2c414d;font-size:12px}td:first-child,th:first-child{text-align:left}a{color:#eab56d}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px}.legend span:first-child{color:#65c4aa}.legend span:last-child{color:#ef8b87}pre{white-space:pre-wrap;font-size:11px}.note{font-size:12px}footer{font-size:12px;color:#9bb0bd;margin:25px 0}@media(max-width:680px){main{padding:20px 12px}.panel{padding:14px}h1{font-size:23px}.controls label:first-child{width:100%}.stats{grid-template-columns:repeat(2,1fr)}.stat strong{font-size:19px}#price-chart{height:310px}#equity-chart{height:230px}}
</style><main><div class="eyebrow">观市 MARKET STUDIO / STRATEGY LAB</div><h1>对照真实走势，看策略何时进、何时出。</h1><p>42个预声明候选 · 672次分段与分币回放 · 10x · 单笔保证金目标/上限20%净值 · 新开仓时组合保证金上限60%</p><section class="panel"><div class="controls"><label>策略<select id="model">OPTIONS</select></label><label>观察区间<select id="window"><option value="review_month">最近一个月 10/7—11/7</option><option value="full">完整三个月 8/7—11/7</option></select></label><label>标的<select id="symbol"><option>BTC</option><option>ETH</option><option>SOL</option></select></label><label>播放步幅<select id="step"><option value="6">逐日</option><option value="1">逐4小时</option></select></label><button id="reset">从头回放</button><button id="play">播放</button><button id="next">下一步</button></div><p id="selection-note" class="note"></p><div class="slider"><span>回放进度</span><input id="progress" type="range" min="1" max="186" value="186" aria-label="回放进度"><time id="replay-time"></time></div></section><section class="stats"><article class="stat"><span>回放时点组合收益</span><strong id="current-return">—</strong></article><article class="stat"><span>全段5m收盘最大回撤</span><strong id="drawdown">—</strong></article><article class="stat"><span>全段组合已平仓笔数</span><strong id="trades">—</strong></article><article class="stat"><span>图上标的价格涨跌</span><strong id="price-change">—</strong></article></section><section class="panel"><h2 id="price-title"></h2><p class="note">箭头表示组合账户该币入场，圆点表示退出。标记落在对应4小时K线上，实际5分钟执行时间见交易明细。回放滑块隐藏此时点之后的K线和交易标记。</p><div id="price-chart"></div></section><section class="panel"><h2>组合账户权益 / USDT</h2><div class="legend"><span>所选策略</span><span>同一风险模型下的原4h基线</span></div><div id="equity-chart"></div><p class="note">图中权益按4小时抽样；全段回撤使用完整5分钟标记价格权益。各窗口从10,000 USDT空仓开始，不能将分段收益直接相加。</p></section><section class="panel table"><h2>回放时点之前的最近平仓（所选标的）</h2><table><thead><tr><th>方向</th><th>入场 / 北京</th><th>退出 / 北京</th><th>入场价</th><th>退出价</th><th>净盈亏</th><th>原因</th></tr></thead><tbody id="trade-rows"></tbody></table><p id="empty" class="note"></p></section><section class="panel table"><h2>部分候选对照（全体42个见实验CSV）</h2><table><thead><tr><th>策略</th><th>三个月收益</th><th>三个月回撤</th><th>最近月收益</th><th>最近月回撤</th><th>最近月笔数</th></tr></thead><tbody>ROWS</tbody></table></section><section class="panel"><h2>怎样解读这些结果</h2><p>低频震荡回归候选在预设的前两段开发筛选中入围，但最近月仅3笔、全部来自SOL，BTC/ETH无交易；仍不足以证明策略稳定。慢速日线趋势＋ATR的事后收益较高，但回撤超出开发门槛，不能作为按最近月收益挑出的推荐策略。</p><p>多空比为账户数量比；主动买卖量、OI、相对量、周转率和近似POC分别进行消融，没有一致增益。统计因子延后一完整周期及5分钟后使用；密集区由5分钟量价近似，不是真实逐价逐笔分布。</p><p>逐仓资金费改变仓位保证金；历史标记价格用于估算结算和强平边界。手续费每边0.06%、不利滑点每边0.05%。5m OHLC不能还原真实盘口、滑点和所有触价时序；本页是历史研究，不发送真实订单。</p></section><footer><a href="../加密 合约 策略 回放 研究.md">研究报告与来源</a> · <a href="experiments.csv">全体实验CSV</a> · <a href="selected-trades.csv">所选组合逐笔CSV</a> · <a href="features.csv">因子审计CSV</a> · <a href="results.json">完整结果JSON</a> · <a href="https://www.tradingview.com/">TradingView Lightweight Charts™</a><details><summary>第三方图表许可</summary><pre>LICENSE</pre></details></footer></main>'''.replace('OPTIONS',options).replace('ROWS',rows).replace('LICENSE',license_text)
    script='''const DATA=PAYLOAD;const el=id=>document.getElementById(id);const fmt=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});const number=v=>v.toLocaleString('en-US',{maximumFractionDigits:2});const L=LightweightCharts;const chart=id=>L.createChart(el(id),{autoSize:true,layout:{background:{color:'#18242b'},textColor:'#9bb0bd'},grid:{vertLines:{color:'#2b3f4b'},horzLines:{color:'#2b3f4b'}},timeScale:{timeVisible:true,secondsVisible:false,tickMarkFormatter:t=>new Date(t*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})},localization:{timeFormatter:t=>fmt(t*1000)}});const price=chart('price-chart');const candles=price.addSeries(L.CandlestickSeries,{upColor:'#65c4aa',downColor:'#ef8b87',borderVisible:false,wickUpColor:'#65c4aa',wickDownColor:'#ef8b87'});const markers=L.createSeriesMarkers(candles,[]);const equity=chart('equity-chart');const actual=equity.addSeries(L.LineSeries,{color:'#65c4aa',lineWidth:2,title:'所选策略'});const baseline=equity.addSeries(L.LineSeries,{color:'#ef8b87',lineWidth:2,title:'原4h基线'});let timer=null;const reasons={stop_loss:'止损',take_profit:'止盈',signal_invalid:'策略退出',end_of_test:'期末退出'};function stop(){if(timer!==null)clearInterval(timer);timer=null;el('play').textContent='播放';}function bars(){const [a,b]=DATA.windows[el('window').value];return DATA.prices[el('symbol').value].filter(r=>r.time>=a&&r.time<b);}function signed(node,value,suffix='%'){node.textContent=(value>=0?'+':'')+value.toFixed(2)+suffix;node.className=value>=0?'positive':'negative';}function render(fit=false){const rows=bars(),n=Math.min(rows.length,Math.max(1,Number(el('progress').value))),shown=rows.slice(0,n);const cut=shown.at(-1).time+14400000;const window=el('window').value,model=el('model').value,symbol=el('symbol').value;const detail=DATA.details[model][window],base=DATA.details.ema_original[window];if(!detail)return;candles.setData(shown.map(r=>({...r,time:r.time/1000})));const points=[];for(const t of detail.trades.filter(t=>t.symbol===symbol)){if(t.entry_at<cut)points.push({time:Math.floor(t.entry_at/14400000)*14400,position:t.side===1?'belowBar':'aboveBar',shape:t.side===1?'arrowUp':'arrowDown',color:t.side===1?'#65c4aa':'#ef8b87',text:(t.side===1?'多入 ':'空入 ')+number(t.entry_price)});if(t.exit_at<cut)points.push({time:Math.floor(t.exit_at/14400000)*14400,position:'aboveBar',shape:'circle',color:'#eab56d',text:reasons[t.exit_reason]||t.exit_reason});}markers.setMarkers(points.sort((a,b)=>a.time-b.time));const curve=detail.equity.filter(p=>p.t<=cut),old=base.equity.filter(p=>p.t<=cut);actual.setData(curve.map(p=>({time:p.t/1000,value:p.equity})));baseline.setData(old.map(p=>({time:p.t/1000,value:p.equity})));signed(el('current-return'),(curve.at(-1).equity/10000-1)*100);el('drawdown').textContent=detail.metrics.max_drawdown_pct.toFixed(2)+'%';el('trades').textContent=detail.metrics.trade_count;const change=(shown.at(-1).close/rows[0].open-1)*100;signed(el('price-change'),change);el('replay-time').textContent=fmt(cut);el('price-title').textContent=symbol+' · 实际4h K线与组合交易';el('selection-note').textContent=DATA.eligible.includes(model)?'开发前两段筛选入围；最近月已被观察，仍需新的前向验证。':'诊断对照；不因事后收益最高就视为已验证策略。';const closed=detail.trades.filter(t=>t.symbol===symbol&&t.exit_at<cut).sort((a,b)=>b.exit_at-a.exit_at).slice(0,20);el('trade-rows').innerHTML=closed.map(t=>`<tr><td>${t.side===1?'做多':'做空'}</td><td>${fmt(t.entry_at)}</td><td>${fmt(t.exit_at)}</td><td>${number(t.entry_price)}</td><td>${number(t.exit_price)}</td><td class="${t.net_pnl>=0?'positive':'negative'}">${t.net_pnl.toFixed(2)}</td><td>${reasons[t.exit_reason]||t.exit_reason}</td></tr>`).join('');el('empty').textContent=closed.length?'显示最近20笔；完整记录见CSV。':'截至当前回放时点，该币尚无已平仓记录。';el('next').disabled=n>=rows.length;if(fit){price.timeScale().fitContent();equity.timeScale().fitContent();}}function resetSelection(){stop();el('progress').max=bars().length;el('progress').value=bars().length;render(true);}for(const id of ['model','window','symbol'])el(id).addEventListener('change',resetSelection);el('progress').addEventListener('input',()=>{stop();render(true);});el('reset').addEventListener('click',()=>{stop();el('progress').value=1;render(true);});function next(){el('progress').value=Math.min(bars().length,Number(el('progress').value)+Number(el('step').value));render(true);if(Number(el('progress').value)>=bars().length)stop();}el('next').addEventListener('click',next);el('play').addEventListener('click',()=>{if(timer!==null){stop();return;}if(Number(el('progress').value)>=bars().length)el('progress').value=1;el('play').textContent='暂停';timer=setInterval(next,250);});el('symbol').value=DATA.default_symbol;resetSelection();'''.replace('PAYLOAD',json.dumps(data,ensure_ascii=False,allow_nan=False).replace('</','<\\/'))
    (output/'replay.html').write_text(html+'<script>'+runtime+'</script><script>'+script+'</script></html>')
    print('Replay:',output/'replay.html')

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('results',type=Path);args=parser.parse_args();write_view(args.results)
